In computer programming, a code smell is any characteristic in the source code of a program that possibly indicates a deeper problem.
Now I will tell you the definition about SonarQube warning 'S112':'Generic exceptions should never be thrown' as given by the SonarQube docu, including an example to help you solve a similar warning:
'Using such generic exceptions as `Error`, `RuntimeException`, `Throwable`, and `Exception` prevents calling methods from handling true, system-generated exceptions differently than application-generated errors.

Noncompliant Code Example


    public void foo(String bar) throws Throwable {  // Noncompliant
      throw new RuntimeException("My Message");     // Noncompliant
    }


Compliant Solution


    public void foo(String bar) {
      throw new MyOwnRuntimeException("My Message");
    }


Exceptions

Generic exceptions in the signatures of overriding methods are ignored, because overriding method has to follow signature of the throw declaration in the superclass. The issue will be raised on superclass declaration of the method (or won’t be raised at all if superclass is not part of the analysis).


    @Override
    public void myMethod() throws Exception {...}


Generic exceptions are also ignored in the signatures of methods that make calls to methods that throw generic exceptions.


    public void myOtherMethod throws Exception {
      doTheThing();  // this method throws Exception
    }


See

  * [MITRE, CWE-397](https://cwe.mitre.org/data/definitions/397) \- Declaration of Throws for Generic Exception 
  * [CERT, ERR07-J.](https://wiki.sei.cmu.edu/confluence/x/_DdGBQ) \- Do not throw RuntimeException, Exception, or Throwable'

Now based on the example, refactor the following Java code to eliminate the 'S112':'Generic exceptions should never be thrown' warning, with specific warning message 'Define and throw a dedicated exception instead of using a generic one.'.
Output the full refactored code (the full file). Don't leave out any part of the code.
The warning is located at the line 'public void tearDown() throws Exception {' (line number 27). Give the changed code using: ```...```.
Java code:
```java
package org.sqlite;

import org.junit.After;
import org.junit.Assume;
import org.junit.Before;
import org.junit.Test;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.ResultSet;
import java.sql.Statement;

import static junit.framework.Assert.assertEquals;
import static junit.framework.Assert.assertTrue;

public class ExtensionTest {
    Connection conn;
    Statement stat;

    @Before
    public void setUp() throws Exception {
        conn = DriverManager.getConnection("jdbc:sqlite:");
        stat = conn.createStatement();
    }

    @After
    public void tearDown() throws Exception {
        if(stat != null)
            stat.close();
        if(conn != null)
            conn.close();

    }

    @Test
    public void extFTS3() throws Exception {
        stat.execute("create virtual table recipe using fts3(name, ingredients)");
        stat.execute("insert into recipe (name, ingredients) values('broccoli stew', 'broccoli peppers cheese tomatoes')");
        stat.execute("insert into recipe (name, ingredients) values('pumpkin stew', 'pumpkin onions garlic celery')");

        ResultSet rs = stat
            .executeQuery("select rowid, name, ingredients from recipe where ingredients match 'onions'");
        assertTrue(rs.next());
        assertEquals("pumpkin stew", rs.getString(2));
    }

    @Test
    public void extFTS5() throws Exception {
        stat.execute("create virtual table recipe using fts5(name, ingredients)");
        stat.execute("insert into recipe (name, ingredients) values('broccoli stew', 'broccoli peppers cheese tomatoes')");
        stat.execute("insert into recipe (name, ingredients) values('pumpkin stew', 'pumpkin onions garlic celery')");

        ResultSet rs = stat
            .executeQuery("select rowid, name, ingredients from recipe where recipe match 'onions'");
        assertTrue(rs.next());
        assertEquals("pumpkin stew", rs.getString(2));
    }

    @Test
    public void extFunctions() throws Exception {
        {
            ResultSet rs = stat.executeQuery("pragma compile_options");
            boolean hasJdbcExtensions = false;
            while (rs.next()) {
                String compileOption = rs.getString(1);
                if (compileOption.equals("JDBC_EXTENSIONS")) {
                    hasJdbcExtensions = true;
                    break;
                }
            }
            rs.close();
            // SQLite has to be compiled with JDBC Extensions for this test to
            // continue.
            Assume.assumeTrue(hasJdbcExtensions);
        }
        {
            ResultSet rs = stat.executeQuery("select cos(radians(45))");
            assertTrue(rs.next());
            assertEquals(0.707106781186548, rs.getDouble(1), 0.000000000000001);
            rs.close();
        }

        {
            ResultSet rs = stat.executeQuery("select reverse(\"ACGT\")");
            assertTrue(rs.next());
            assertEquals("TGCA", rs.getString(1));
            rs.close();
        }
    }


}
